 private void startApprovedServices(){UpdateService.initialize(this);if(dead||startupStarted||!RiskNotice.accepted(this))return;startupStarted=true;prepareBridge(false);refresh();getSharedPreferences("connection",0).edit().putBoolean("appActive",true).apply();startForegroundService(new Intent(this,ConsoleService.class));PhoneCompanion.attach(this);checkBridgeOnResume();sessionHandler.removeCallbacks(sessionTick);sessionHandler.post(sessionTick);if(!android.provider.Settings.canDrawOverlays(this))Toast.makeText(this,"请在设置中授予悬浮窗权限",1).show();if(getSharedPreferences("updates",0).getBoolean("auto",true))UpdateService.check(this,false);}
